def norm(s): return ' '.join(unicodedata.normalize('NFC',s.replace('_',' ').strip().upper()).split())
for cid,(name,levels) in DATA.items():
    words=[]; seen=set()
    for difficulty,raw in levels.items():
        for entry in raw.split(';'):
            word=norm(entry)
            if not word or word in seen: continue
            seen.add(word); words.append({'text':word,'difficulty':difficulty})
    out={'version':1,'language':'cs-CZ','category':{'id':cid,'name':name},'words':words}
    (ROOT/f'{cid}.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
files=[]
for f in sorted(ROOT.glob('*.json')):
    if f.name == 'dictionary.json': continue
    d=json.loads(f.read_text(encoding='utf-8'))
    counts={str(n):sum(w['difficulty']==n for w in d['words']) for n in (1,2,3)}
    files.append({'id':d['category']['id'],'name':d['category']['name'],'file':f.name,'wordCount':len(d['words']),'difficultyCounts':counts})
(ROOT/'dictionary.json').write_text(json.dumps({'version':1,'language':'cs-CZ','categories':files},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print('\n'.join(f"{x['id']}: {x['wordCount']} (L1 {x['difficultyCounts']['1']}, L2 {x['difficultyCounts']['2']}, L3 {x['difficultyCounts']['3']})" for x in files))
